mapper.select:
SELECT  FROM harness_thread_state t
WHERE t.organization_uuid = #{ref.OrganizationUUID} AND t.workspace_uuid = #{ref.WorkspaceUUID}
  AND t.session_uuid = #{ref.SessionUUID} AND t.thread_uuid = t.session_uuid
  AND t.execution->>'resume_input_uuid' = #{ref.UUID}
  AND t.execution->>'resume_input_kind' = #{kind}
  AND t.execution->>'state' IN ('pending', 'running', 'waiting_tool')

mapper.update:
UPDATE harness_thread_state
SET execution = (execution - 'wake_pending') || jsonb_build_object(
    'state', 'running', 'worker_epoch', CAST(#{params.Lease.Epoch} AS bigint),
    'lease_until', CAST(#{params.LeaseUntil} AS timestamptz), 'model_started_at', NULL,
    'attempts', CAST(execution->>'attempts' AS integer) + 1)
WHERE thread_uuid = session_uuid AND execution_input_uuid = #{params.Lease.Ref.UUID}
  AND organization_uuid = #{params.Lease.Ref.OrganizationUUID}
  AND workspace_uuid = #{params.Lease.Ref.WorkspaceUUID} AND session_uuid = #{params.Lease.Ref.SessionUUID}
  AND (execution->>'state' IN ('pending', 'waiting_tool') OR
    (execution->>'state' = 'running' AND CAST(execution->>'lease_until' AS timestamptz) <= NOW()))

UPDATE code_sessions SET worker_lease_expires_at = #{params.LeaseUntil}
WHERE uuid = #{params.Lease.CodeSessionUUID} AND organization_uuid = #{params.Lease.Ref.OrganizationUUID}
  AND workspace_uuid = #{params.Lease.Ref.WorkspaceUUID} AND session_uuid = #{params.Lease.Ref.SessionUUID}
  AND current_worker_epoch = #{params.Lease.Epoch} AND worker_lease_expires_at > NOW()
  AND status = 'active' AND deleted_at IS NULL

UPDATE code_sessions SET worker_lease_expires_at = NULL
WHERE uuid = #{lease.CodeSessionUUID} AND organization_uuid = #{lease.Ref.OrganizationUUID}
  AND workspace_uuid = #{lease.Ref.WorkspaceUUID} AND session_uuid = #{lease.Ref.SessionUUID}
  AND current_worker_epoch = #{lease.Epoch}

mapper.select:
SELECT current_worker_epoch FROM code_sessions
WHERE uuid = #{lease.CodeSessionUUID} AND organization_uuid = #{lease.Ref.OrganizationUUID}
  AND workspace_uuid = #{lease.Ref.WorkspaceUUID} AND session_uuid = #{lease.Ref.SessionUUID}
  AND current_worker_epoch = #{lease.Epoch} AND worker_lease_expires_at > NOW()
  AND status = 'active' AND deleted_at IS NULL
FOR UPDATE

