UPDATE harness_conversation_history
SET execution_turn_uuid = #{params.TurnUUID}, tool_uuid = #{params.ToolUUID}
WHERE organization_uuid = #{params.Key.Scope.OrganizationUUID} AND workspace_uuid = #{params.Key.Scope.WorkspaceUUID}
  AND session_uuid = #{params.Key.Scope.SessionUUID} AND thread_uuid = #{params.Key.UUID}
  AND message_id = #{params.MessageID} AND tool_uuid IS NULL

UPDATE harness_conversation_history
SET tool_result_text = #{params.Text,sensitive=true}, tool_result_failed = #{params.Failed}
WHERE organization_uuid = #{params.Ref.OrganizationUUID} AND workspace_uuid = #{params.Ref.WorkspaceUUID}
  AND session_uuid = #{params.Ref.SessionUUID} AND execution_turn_uuid = #{params.Ref.UUID}
  AND tool_uuid = #{params.ToolUUID} AND tool_result_text IS NULL
